import org.junit.*;import org.junit.runners.MethodSorters;import static org.junit.Assert.*;import java.net.*;import java.io.*;import java.nio.file.*;import java.sql.*;import java.util.*;import java.util.regex.*;import com.fasterxml.jackson.databind.*;import org.apache.poi.xssf.usermodel.*;
@FixMethodOrder(MethodSorters.NAME_ASCENDING)
public class FullFunctionalTest {
 static ObjectMapper om=new ObjectMapper();static JsonNode env;static Connection db;static final String base="http://127.0.0.1:18084";static String cookie="";static long admin=1812120000000000L;static Path out=Paths.get("verification/results/junit");
 @BeforeClass public static void setup()throws Exception{Files.createDirectories(out);env=om.readTree(new File("verification/environment.json"));db=DriverManager.getConnection("jdbc:mysql://127.0.0.1:13306/"+env.path("db").asText()+"?useSSL=false&serverTimezone=Asia/Shanghai","root","");ok(post("/login","username=testadmin&password=Test2026ok&rememberMe=false"));}
 @Before public void loginForEach()throws Exception{cookie="";ok(post("/login","username=testadmin&password=Test2026ok&rememberMe=false"));} @AfterClass public static void close()throws Exception{if(db!=null)db.close();}
 static String form(String...v)throws Exception{StringJoiner j=new StringJoiner("&");for(int i=0;i<v.length;i+=2)j.add(URLEncoder.encode(v[i],"UTF-8")+"="+URLEncoder.encode(v[i+1],"UTF-8"));return j.toString();}
 static byte[] request(String method,String path,byte[] body,String contentType)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setRequestMethod(method);if(!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);c.setRequestProperty("X-Requested-With","XMLHttpRequest");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",contentType);c.getOutputStream().write(body);}for(Map.Entry<String,List<String>> h:c.getHeaderFields().entrySet())if(h.getKey()!=null&&h.getKey().equalsIgnoreCase("Set-Cookie"))for(String set:h.getValue())if(set.startsWith("JSESSIONID="))cookie=set.split(";",2)[0];InputStream in=c.getResponseCode()>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream();if(in!=null){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)b.write(buf,0,n);}return b.toByteArray();}
 static String get(String p)throws Exception{return new String(request("GET",p,null,null),"UTF-8");}static JsonNode post(String p,String v)throws Exception{return om.readTree(request("POST",p,v.getBytes("UTF-8"),"application/x-www-form-urlencoded"));}static void ok(JsonNode j){assertEquals(j.toString(),0,j.path("code").asInt(-9));}static long scalar(String q)throws Exception{try(Statement s=db.createStatement();ResultSet r=s.executeQuery(q)){assertTrue(r.next());return r.getLong(1);}}static void sql(String q)throws Exception{try(Statement s=db.createStatement()){s.execute(q);}}static String variable(String html,String name){Matcher m=Pattern.compile("(?:var |[,;])\\s*"+name+"\\s*=\\s*['\"]([^'\"]+)['\"]").matcher(html);assertTrue("missing JS variable "+name,m.find());return m.group(1);}
 @Test public void a_loginAndAuthentication()throws Exception{String saved=cookie;cookie="";JsonNode denied=post("/login","username=testadmin&password=wrong&rememberMe=false");assertNotEquals(0,denied.path("code").asInt());cookie="";assertFalse(get("/campus/wallet/data").contains("balance"));cookie=saved;assertTrue(get("/index").contains("测试管理员"));}
 @Test public void b_userMaintenanceAndAutomaticWallet()throws Exception{ok(post("/system/user/add",form("loginName","junitperson","userName","JUnit新增人员","password","Test2026ok","sex","0","status","0","phonenumber","13800000002","identity","本科生")));assertEquals(1,scalar("select count(*) from campus_wallet w join sys_user u on u.user_id=w.user_id where u.login_name='junitperson'"));long id=scalar("select user_id from sys_user where login_name='junitperson'");ok(post("/system/user/edit",form("userId",""+id,"loginName","junitperson","userName","JUnit修改人员","sex","0","status","0","phonenumber","13800000002","identity","本科生")));assertTrue(post("/system/user/list","loginName=junitperson&pageNum=1&pageSize=10").toString().contains("JUnit修改人员"));}
 @Test public void c_excelTemplateImportExport()throws Exception{JsonNode template=post("/system/excelImport/downloadExcelModel","importType=1");ok(template);byte[] x=request("GET","/common/download?fileName="+URLEncoder.encode(template.path("msg").asText(),"UTF-8")+"&delete=false",null,null);org.apache.poi.ss.usermodel.Workbook book=org.apache.poi.ss.usermodel.WorkbookFactory.create(new ByteArrayInputStream(x));assertTrue(book.getSheetAt(0).getRow(0).getLastCellNum()>=14);org.apache.poi.ss.usermodel.Row row=book.getSheetAt(0).createRow(1);String[] values={"junitimport","JUnit导入人员","男","test@example.invalid","13800000003","2000-01-01","汉族","测试院系","测试地址","本科生","在籍","计算机","测试班","4"};for(int i=0;i<values.length;i++)row.createCell(i).setCellValue(values[i]);ByteArrayOutputStream payload=new ByteArrayOutputStream();book.write(payload);book.close();Files.write(out.resolve("user-import.xlsx"),payload.toByteArray());String boundary="TestBoundary123";ByteArrayOutputStream body=new ByteArrayOutputStream();body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"importType\"\r\n\r\n1\r\n--"+boundary+"\r\nContent-Disposition: form-data; name=\"excelFile\"; filename=\"users.xlsx\"\r\nContent-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\r\n\r\n").getBytes("UTF-8"));body.write(payload.toByteArray());body.write(("\r\n--"+boundary+"--\r\n").getBytes("UTF-8"));JsonNode imported=om.readTree(request("POST","/system/excelImport/save",body.toByteArray(),"multipart/form-data; boundary="+boundary));ok(imported);assertEquals(imported.toString(),1,imported.path("data").path("successNum").asInt());assertEquals(1,scalar("select count(*) from sys_user where login_name='junitimport'"));JsonNode exported=post("/system/user/export","loginName=junitimport");ok(exported);byte[] bytes=request("GET","/common/download?fileName="+URLEncoder.encode(exported.path("msg").asText(),"UTF-8")+"&delete=false",null,null);assertTrue(bytes.length>100);Files.write(out.resolve("user-export.xlsx"),bytes);}
 @Test public void d_gateEntryExitAndExport()throws Exception{long before=scalar("select count(*) from gate_in_out where user_id="+admin);ok(post("/system/gateInOut/add","kind=1"));ok(post("/system/gateInOut/add","kind=2"));assertEquals(before+2,scalar("select count(*) from gate_in_out where user_id="+admin));assertTrue(post("/system/gateInOut/listMy","pageNum=1&pageSize=10").path("total").asInt()>=2);ok(post("/system/gateInOut/export",""));}
 @Test public void e_attendanceCodeAndSignIn()throws Exception{ok(post("/system/projectInfo/add",form("projectName","JUnit考勤","startTime","00:00:00","endTime","23:59:59","remark","自动化测试")));long id=scalar("select project_id from project_info where project_name='JUnit考勤' limit 1");assertNotEquals(0,post("/system/joinProject","projectId=-1").path("code").asInt());ok(post("/system/joinProject","projectId="+id));ok(post("/system/projectAttend/add",""));assertEquals(1,scalar("select count(*) from project_attend where project_id="+id+" and user_id="+admin+" and status in (0,1)"));ok(post("/system/projectAttend/exportMy",""));}
 @Test public void f_libraryBorrowReturnAndRepeatReturn()throws Exception{sql("insert into book_info(book_id,book_name,book_num) values(880001,'JUnit测试图书',2) on duplicate key update book_num=2");ok(post("/system/bookBorrowRecord/add","bookId=880001"));assertEquals(1,scalar("select book_num from book_info where book_id=880001"));long id=scalar("select id from book_borrow_record where book_id=880001 limit 1");ok(post("/system/bookBorrowRecord/edit","id="+id+"&bookId=999999"));ok(post("/system/bookBorrowRecord/edit","id="+id));assertEquals(2,scalar("select book_num from book_info where book_id=880001"));sql("insert into book_info(book_id,book_name,book_num) values(880002,'零库存图书',0) on duplicate key update book_num=0");assertNotEquals(0,post("/system/bookBorrowRecord/add","bookId=880002").path("code").asInt(-1));assertEquals(0,scalar("select count(*) from book_borrow_record where book_id=880002"));}
 @Test public void g_cardIssueWriteCancelReissue()throws Exception{String page=get("/system/user/card/880001"),token=variable(page,"token"),key=variable(page,"key");ok(post("/system/user/card/880001",form("action","issue","token",token,"requestKey",key)));ok(post("/system/user/card/880001",form("action","write","token",token,"requestKey",key)));ok(post("/system/user/card/880001",form("action","write","token",token,"requestKey",key)));assertEquals(1,scalar("select write_count from campus_card where user_id=880001"));ok(post("/system/user/card/880001",form("action","cancel","token",token)));assertEquals(0,scalar("select count(*) from campus_card where user_id=880001"));assertEquals(100,scalar("select balance from campus_wallet where user_id=880001"));ok(post("/system/user/card/880001",form("action","issue","token",token)));}
 @Test public void h_walletRechargePayLostRestoreAndLedger()throws Exception{String token=variable(get("/campus/wallet/detail/880001"),"token");JsonNode receipt=post("/campus/wallet/trade",form("user","880001","kind","RECHARGE","amount","10.00","key","junit-recharge-00000001","token",token));assertTrue(receipt.toString(),receipt.has("transaction_no"));JsonNode retry=post("/campus/wallet/trade",form("user","880001","kind","RECHARGE","amount","10.00","key","junit-recharge-00000001","token",token));assertEquals(receipt.path("transaction_no"),retry.path("transaction_no"));post("/campus/wallet/trade",form("user","880001","kind","PAY","amount","5.00","merchant","1","key","junit-pay-00000001","token",token));assertEquals(105,scalar("select balance from campus_wallet where user_id=880001"));assertTrue(post("/campus/wallet/status",form("user","880001","status","LOST","token",token)).path("ok").asBoolean());assertTrue(post("/campus/wallet/trade",form("user","880001","kind","PAY","amount","1.00","merchant","1","key","junit-lost-00000001","token",token)).has("error"));assertTrue(post("/campus/wallet/status",form("user","880001","status","ACTIVE","token",token)).path("ok").asBoolean());assertTrue(get("/campus/wallet/history?user=880001&page=1").contains("junit")||scalar("select count(*) from campus_ledger where user_id=880001")>=2);}
 @Test public void i_permissionAndCrossUserAccess()throws Exception{String saved=cookie;cookie="";ok(post("/login","username=teststudent&password=Test2026ok&rememberMe=false"));String response=get("/campus/wallet/data?user=880002");assertFalse(response,response.contains("testother"));assertTrue(response,response.contains("权限")||response.contains("error"));assertTrue(post("/system/user/add",form("loginName","forbidden","userName","越权人员")).toString().contains("权限"));assertEquals(0,scalar("select count(*) from sys_user where login_name='forbidden'"));cookie=saved;}
}



